USE seven_coffee;

-- Upgrade the existing customer/admin role model for the admin portal.
-- Run this after seven.sql and before enabling the real login API.
ALTER TABLE users
  MODIFY role ENUM('customer','owner','staff') NOT NULL DEFAULT 'customer';

-- Example account records should be inserted with password_hash values generated by PHP password_hash().
-- Do not store plain-text passwords in the database.
-- Example:
-- INSERT INTO users (name,email,password_hash,role) VALUES
-- ('SEVEN Owner','owner@sevencoffee.ph','<PASSWORD_HASH>','owner'),
-- ('SEVEN Staff','staff@sevencoffee.ph','<PASSWORD_HASH>','staff');
